suppressPackageStartupMessages(library(INLA));O<-file.path(Sys.getenv("R2_CODE_ROOT","."),"output/cpo_diagnostics");z<-readRDS(file.path(O,'loo_fits/Total_925.rds'));s<-inla.posterior.sample(100000,z,selection=list(Predictor=925),num.threads='1:1',seed=261122L);eta<-sapply(s,function(v)v$latent[1]);size<-sapply(s,function(v)v$hyperpar[1]);lp<-dnbinom(865,size=size,mu=exp(eta),log=TRUE);p<-exp(lp);r<-data.frame(group='Total',index=925,n=length(p),cpo=mean(p),mcse=sd(p)/sqrt(length(p)),relative_mcse=sd(p)/sqrt(length(p))/mean(p),eta_mean=mean(eta),eta_se=sd(eta)/sqrt(length(eta)),eta_summary=z$summary.linear.predictor$mean[925]);print(r);write.csv(r,file.path(O,'precision_Namwon.csv'),row.names=FALSE)
